@@ -30,6 +30,18 @@ test("RF-003: una factura emitida no se puede modificar", () => {
   assert.throws(() => { "use strict"; f.totalCentavos = 1; }, TypeError);
 });

+test("RF-004: descuento por línea en porcentaje", () => {
+  const f = calcularFactura([{ cantidad: 2, precioUnitarioCentavos: 1000, descuentoPorcentaje: 10 }]);
+  assert.equal(f.totalCentavos, 1800);
+  // redondeo al centavo: 333 * 15 % = 49,95 → 50 de descuento
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 333, descuentoPorcentaje: 15 }]).totalCentavos, 283);
+  // sin descuento = 0 %
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500 }]).totalCentavos, 500);
+  assert.equal(calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500, descuentoPorcentaje: 100 }]).totalCentavos, 0);
+  for (const d of [-1, 101, NaN, "10"])
+    assert.throws(() => calcularFactura([{ cantidad: 1, precioUnitarioCentavos: 500, descuentoPorcentaje: d }]), RangeError);
+});
